record Money(BigDecimal amount, Currency currency) {
    Money {
        Objects.requireNonNull(amount);
        Objects.requireNonNull(currency);
    }
    Money add(Money other) {
        if (!currency.equals(other.currency())) {
            throw new IllegalArgumentException("Currency mismatch");
        }
        return new Money(amount.add(other.amount()), currency);
    }
}

interface DiscountPolicy {
    BigDecimal discount(BigDecimal subtotal);
}
class Checkout {
    private final DiscountPolicy policy;
    Checkout(DiscountPolicy policy) { this.policy = policy; }
    BigDecimal total(BigDecimal subtotal) {
        return subtotal.subtract(policy.discount(subtotal));
    }
}

// Single-process sketch: synchronization covers refill AND consume.
synchronized boolean allow(long nowNanos) {
    double elapsed = (nowNanos - lastNanos) / 1_000_000_000.0;
    tokens = Math.min(capacity, tokens + elapsed * tokensPerSecond);
    lastNanos = nowNanos;
    if (tokens < 1) return false;
    tokens -= 1;
    return true;
}

